type Cell = [number, number];

const areNeighbors = ([ax, ay]: Cell, [bx, by]: Cell): boolean =>
  !(ax === bx && ay === by) && Math.abs(ax - bx) <= 1 && Math.abs(ay - by) <= 1;

const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((other) => areNeighbors(cell, other)).length;

const survives = (liveNeighbors: number): boolean =>
  liveNeighbors === 2 || liveNeighbors === 3;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => survives(countLiveNeighbors(cell, liveCells)));
}

