python3 - <<'EOF'
p='src/game-of-life.ts'
s=open(p).read()
s=s.replace('''export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => survives(countLiveNeighbors(cell, liveCells)));
}''','''export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) => survives(countLiveNeighbors(cell, liveCells)));
  const liveKeys = new Set(liveCells.map(([x, y]) => `${x},${y}`));
  const deadCandidates = new Map<string, Cell>();
  for (const [x, y] of liveCells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const key = `${x + dx},${y + dy}`;
        if (!liveKeys.has(key)) deadCandidates.set(key, [x + dx, y + dy]);
      }
    }
  }
  const births = [...deadCandidates.values()].filter(
    (cell) => countLiveNeighbors(cell, liveCells) === 3,
  );
  return [...survivors, ...births];
}''')
open(p,'w').write(s)
EOF
